			fmt.Sprintf("%x", p.Tx.Content) != fmt.Sprintf("%x", orig.Content) ||
			fmt.Sprintf("%x", p.Tx.Signature) != fmt.Sprintf("%x", orig.Signature) {
			t.Fatalf("pending tx %s lost original content or valid signature: %+v", id, p.Tx)
		}
